use pencil_readonly_accounting::{qualify,exact_diff,fixed_controls};
use serde_json::{Value,json};
fn fixture()->(Value,Value){
 let nonce="11111111-2222-4333-8444-555555555555";let id="c".repeat(64);let image=format!("sha256:{}","d".repeat(64));let name=format!("isolab-runtime-q-{nonce}");
 let expected=json!({"container_id":id,"image_id":image,"container_name":name,"owner_nonce":nonce,"fixtures_source":"/review/fixtures","gate_source":"/review/gate"});
 let inspect=json!({"Id":id,"Image":image,"Name":format!("/{name}"),"Config":{"User":"1000:1000","Entrypoint":["/qualification/exec-gate"],"Labels":{"isolab.runtime-qualification.owner":nonce}},"State":{"Running":false,"ExitCode":0},"HostConfig":{"ReadonlyRootfs":true,"NetworkMode":"none","PidsLimit":1,"Memory":536870912,"MemorySwap":536870912,"NanoCpus":1000000000,"CapDrop":["ALL"],"SecurityOpt":["no-new-privileges"],"Privileged":false,"PidMode":"","UTSMode":"","IpcMode":"private","CgroupnsMode":"private","Devices":null,"DeviceRequests":[],"CapAdd":[],"Tmpfs":{"/tmp":"rw,noexec,nosuid,nodev,size=16m,mode=1777","/work":"rw,noexec,nosuid,nodev,size=16m,mode=1777"}},"Mounts":[{"Type":"bind","Destination":"/qualification/exec-gate","Source":"/review/gate","RW":false},{"Type":"bind","Destination":"/fixtures","Source":"/review/fixtures","RW":false},{"Type":"tmpfs","Destination":"/tmp"},{"Type":"tmpfs","Destination":"/work"}]});(inspect,expected)
}
fn main(){let out=run();match out{Ok(v)=>println!("{}",serde_json::to_string_pretty(&v).unwrap()),Err(e)=>{eprintln!("{e}");std::process::exit(1)}}}
fn run()->Result<Value,String>{let producer=fixed_controls()?;if producer["count"]!=58||producer["all_expected"]!=true{return Err("producer inventory".into())}let (c,e)=fixture();let raw=b"A /qualification/exec-gate\nA /fixtures\nA /qualification\n";let mut cases=Vec::new();
 for (case,code) in [("Q1",0),("Q2",2),("Q3",125)] {let mut x=c.clone();x["State"]["ExitCode"]=json!(code);let v=qualify(case,0,raw,&x,&e)?;if v["no_writes_claim"]!=false||!v["writer_attribution"].is_null(){return Err("claim flags".into())}cases.push(json!({"name":format!("independent-{case}"),"accepted":true}));}
 for (name,path,value) in [
 ("boolean-exit","/State/ExitCode",json!(false)),("negative-exit","/State/ExitCode",json!(-1)),("missing-exit","/State/ExitCode",Value::Null),
 ("float-pids","/HostConfig/PidsLimit",json!(1.0)),("string-memory","/HostConfig/Memory",json!("536870912")),("null-rootfs","/HostConfig/ReadonlyRootfs",Value::Null),
 ("object-devices","/HostConfig/Devices",json!({})),("duplicate-security-option","/HostConfig/SecurityOpt",json!(["no-new-privileges","no-new-privileges"])),
 ("tmpfs-type","/HostConfig/Tmpfs/~1tmp",json!(1)),("unknown-tmpfs-option","/HostConfig/Tmpfs/~1work",json!("rw,noexec,nosuid,nodev,size=16m,mode=1777,exec")),
 ("gate-writable","/Mounts/0/RW",json!(true)),("gate-source","/Mounts/0/Source",json!("/different")),("duplicate-tmpfs","/Mounts/3/Destination",json!("/tmp")),("unapproved-tmpfs","/Mounts/3/Destination",json!("/outside")),
 ("label-type","/Config/Labels/isolab.runtime-qualification.owner",json!(5)),("entrypoint-extra","/Config/Entrypoint",json!(["/qualification/exec-gate","extra"]))] {
 let mut x=c.clone();*x.pointer_mut(path).ok_or(format!("fixture pointer {path}"))?=value;let err=qualify("Q1",0,raw,&x,&e).err().ok_or(format!("unexpected accept {name}"))?;cases.push(json!({"name":name,"accepted":false,"error":err}));}
 for (name,key,value) in [("context-missing-id","container_id",Value::Null),("uppercase-id","container_id",json!("C".repeat(64))),("nonce-mismatch","owner_nonce",json!("00000000-0000-4000-8000-000000000000")),("relative-fixture","fixtures_source",json!("relative"))] {let mut x=e.clone();x[key]=value;let err=qualify("Q1",0,raw,&c,&x).err().ok_or(name)?;cases.push(json!({"name":name,"accepted":false,"error":err}));}
 for (name,b) in [("nul-suffix",[raw.as_slice(),b"\0"].concat()),("leading-newline",[b"\n",raw.as_slice()].concat()),("bare-cr",b"A /fixtures\rA /qualification\rA /qualification/exec-gate\n".to_vec()),("parent-path",b"A /fixtures\nA /qualification\nA /qualification/../qualification/exec-gate\n".to_vec())] {let err=exact_diff(&b).err().ok_or(name)?;cases.push(json!({"name":name,"accepted":false,"error":err}));}
 for (name,case,rc) in [("wrong-case","q1",0),("transport-signal","Q1",-9),("transport-failure","Q1",42)] {let err=qualify(case,rc,raw,&c,&e).err().ok_or(name)?;cases.push(json!({"name":name,"accepted":false,"error":err}));}
 // Deliberate acceptance boundaries inherited from metadata/set predicates.
 let mut duplicate=c.clone();duplicate["HostConfig"]["Tmpfs"]["/tmp"]=json!("rw,rw,noexec,nosuid,nodev,size=16m,mode=1777");qualify("Q1",0,raw,&duplicate,&e)?;cases.push(json!({"name":"duplicate-identical-tmpfs-option","accepted":true,"scope":"options are a set, matching original source"}));
 let mut cc=c.clone();let mut ee=e.clone();ee["fixtures_source"]=json!("/review/../fixtures");cc["Mounts"][1]["Source"]=ee["fixtures_source"].clone();qualify("Q1",0,raw,&cc,&ee)?;cases.push(json!({"name":"matched-noncanonical-absolute-source","accepted":true,"scope":"filesystem canonicalization and fixture custody belong to unported supervisor"}));
 Ok(json!({"schema":"native-adapter-independent-review/v1","accepted":true,"producer_controls":producer["count"],"independent_count":cases.len(),"cases":cases,"scientific_execution":false,"docker_invoked":false,"supervisor_invoked":false,"full_supervisor_integrated":false}))}
